    # Check if it's stripes mode: non-zero rows are uniform
    non_zero_rows = [r for r in grid if any(c != 0 for c in r)]

    if len(non_zero_rows) == 0:
        return [[0]*w for _ in range(h)]

    # Check if all non-zero rows have uniform color
    is_stripes = all(all(c == non_zero_rows[0][0] for c in row) for row in non_zero_rows)

    if is_stripes:
        # Stripes mode: sort descending, rotate left 1, repeat
        non_zero_rows.sort(key=lambda r: -r[0])
        if len(non_zero_rows) > 1:
            non_zero_rows = non_zero_rows[1:] + [non_zero_rows[0]]

        # Repeat to fill grid
        pattern_len = len(non_zero_rows)
        out = [non_zero_rows[i % pattern_len] for i in range(h)]
        return out
    else:
        # Diagonal mode: learn from sparse points
        mapping = {}
        for r in range(h):
            for c in range(w):
                val = grid[r][c]
                if val != 0:
                    s = (r + c) % 6
                    if s not in mapping:
                        mapping[s] = val

        # Fill grid using mapping
        out = []
        for r in range(h):
            row = []
            for c in range(w):
                s = (r + c) % 6
                row.append(mapping.get(s, 0))
            out.append(row)
        return out
